    page=apis.venmo.show_sent_payment_requests(access_token=token, status='approved', page_index=i, page_limit=20)
    # page might have different shape; try to access list
    print('page_index', i, 'keys', list(page.keys()))
    if 'payment_requests' in page:
        reqs=page['payment_requests']
    elif 'success' in page:
        reqs=page['success']
    else:
        reqs=page.get('data', []) if isinstance(page, dict) else []
    print('num_reqs', len(reqs))
    if not reqs:
        break
    all_reqs.extend(reqs)
    i+=1

print('total approved sent payment requests', len(all_reqs))
# filter to receiver.name containing Robert
rob=[]
for r in all_reqs:
    name=r.get('receiver',{}).get('name','')
    if 'robert' in str(name).lower():
        rob.append(r)
print('matched receiver name Robert:', len(rob))
