from datetime import datetime

def parse_dt(s):
    if not s:
        return datetime.min
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s,'%Y-%m-%dT%H:%M:%S')
        except Exception:
            return datetime.min

rob_sorted=sorted(rob, key=lambda r: (parse_dt(r.get('approved_at')), parse_dt(r.get('created_at'))), reverse=True)
for r in rob_sorted[:5]:
    print('id', r.get('payment_request_id'),'amount',r.get('amount'),'receiver',r.get('receiver'), 'approved_at', r.get('approved_at'),'created_at', r.get('created_at'))

# also show last overall if none matched
if not rob_sorted and all_reqs:
    # sort overall by approved_at
    sorted_all=sorted(all_reqs, key=lambda r: (parse_dt(r.get('approved_at')), parse_dt(r.get('created_at'))), reverse=True)
    last=sorted_all[0]
    print('last approved overall receiver', last.get('receiver'), 'amount', last.get('amount'), 'id', last.get('payment_request_id'))

